const clamp=value=>Math.max(0,Math.min(255,value));
export function hdDimensions(width,height,scale=2){if(![1,2,4].includes(scale))throw Error('请选择 1、2 或 4 倍');const w=width*scale,h=height*scale;if(w>8192||h>8192||w*h>16*1024*1024)throw Error(`目标为 ${w} × ${h} px，超过 8192 边长或 1600 万像素限制，请降低倍数或先缩小原图`);return {width:w,height:h};}
const sinc=value=>value===0?1:Math.sin(Math.PI*value)/(Math.PI*value);
const lanczos=value=>Math.abs(value)>=3?0:sinc(value)*sinc(value/3);
function weights(input,output,wrap){const scale=input/output;return Array.from({length:output},(_,index)=>{const position=(index+.5)*scale-.5,start=Math.ceil(position-3),list=[];let sum=0;for(let i=start;i<=Math.floor(position+3);i++){const weight=lanczos(position-i);if(Math.abs(weight)<1e-9)continue;const pixel=wrap?(i%input+input)%input:Math.max(0,Math.min(input-1,i));list.push([pixel,weight]);sum+=weight;}return list.map(([pixel,weight])=>[pixel,weight/sum]);});}
export function upscalePattern(source,{scale=2,sharpen=.3,seamless=false}={},progress=()=>{}){
  const {width,height}=hdDimensions(source.width,source.height,scale);if(!Number.isFinite(sharpen)||sharpen<0||sharpen>1)throw Error('锐度参数无效');const wx=weights(source.width,width,seamless),wy=weights(source.height,height,seamless),intermediate=new Float32Array(width*source.height*4),output=new Uint8ClampedArray(width*height*4);
  // Premultiplied alpha prevents dark outlines around transparent motifs.
  for(let y=0;y<source.height;y++){for(let x=0;x<width;x++){const index=(y*width+x)*4;for(const [pixel,weight]of wx[x]){const offset=(y*source.width+pixel)*4,alpha=source.data[offset+3]/255;for(let c=0;c<3;c++)intermediate[index+c]+=source.data[offset+c]*alpha*weight;intermediate[index+3]+=alpha*weight;}}if(y%64===0)progress(Math.round(y/source.height*35));}
  for(let y=0;y<height;y++){for(let x=0;x<width;x++){const index=(y*width+x)*4,values=[0,0,0,0];for(const [pixel,weight]of wy[y]){const offset=(pixel*width+x)*4;for(let c=0;c<4;c++)values[c]+=intermediate[offset+c]*weight;}const alpha=Math.max(0,Math.min(1,values[3]));for(let c=0;c<3;c++)output[index+c]=alpha>.001?clamp(values[c]/alpha):0;output[index+3]=alpha*255;}if(y%64===0)progress(35+Math.round(y/height*45));}
  if(sharpen>0){const original=new Uint8ClampedArray(output),coordinate=(value,size)=>seamless?(value%size+size)%size:Math.max(0,Math.min(size-1,value));for(let y=0;y<height;y++){for(let x=0;x<width;x++){const index=(y*width+x)*4;if(original[index+3]<250)continue;for(let c=0;c<3;c++){let sum=0,min=255,max=0;for(let oy=-1;oy<=1;oy++)for(let ox=-1;ox<=1;ox++){const value=original[(coordinate(y+oy,height)*width+coordinate(x+ox,width))*4+c];sum+=value;min=Math.min(min,value);max=Math.max(max,value);}const detail=original[index+c]-sum/9;output[index+c]=Math.max(min,Math.min(max,original[index+c]+detail*sharpen*1.5));}}if(y%128===0)progress(80+Math.round(y/height*19));}}
  progress(100);return {width,height,data:output};
}
